        }
        return ans;
    }
};

class Solution {
    private int getArea(int[][] grid, int r1, int c1, int r2, int c2) {
        int minR = Integer.MAX_VALUE, maxR = -1;
        int minC = Integer.MAX_VALUE, maxC = -1;
        boolean hasOne = false;
        for (int r = r1; r <= r2; ++r) {
            for (int c = c1; c <= c2; ++c) {
                if (grid[r][c] == 1) {
                    hasOne = true;
                    minR = Math.min(minR, r);
                    maxR = Math.max(maxR, r);
                    minC = Math.min(minC, c);
                    maxC = Math.max(maxC, c);
                }
            }
        }
        if (!hasOne) return 0;
        return (maxR - minR + 1) * (maxC - minC + 1);
    }
    public int minimumSum(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        int ans = Integer.MAX_VALUE;
        for (int i = 0; i < m - 2; ++i) {
            for (int j = i + 1; j < m - 1; ++j) {
                ans = Math.min(ans, getArea(grid, 0, 0, i, n - 1) + getArea(grid, i + 1, 0, j, n - 1) + getArea(grid, j + 1, 0, m - 1, n - 1));
            }
        }
        for (int j = 0; j < n - 2; ++j) {
            for (int k = j + 1; k < n - 1; ++k) {
                ans = Math.min(ans, getArea(grid, 0, 0, m - 1, j) + getArea(grid, 0, j + 1, m - 1, k) + getArea(grid, 0, k + 1, m - 1, n - 1));
            }
        }
        for (int i = 0; i < m - 1; ++i) {
            for (int j = 0; j < n - 1; ++j) {
                ans = Math.min(ans, getArea(grid, 0, 0, i, j) + getArea(grid, 0, j + 1, i, n - 1) + getArea(grid, i + 1, 0, m - 1, n - 1));
                ans = Math.min(ans, getArea(grid, 0, 0, i, n - 1) + getArea(grid, i + 1, 0, m - 1, j) + getArea(grid, i + 1, j + 1, m - 1, n - 1));
            }
        }
        for (int j = 0; j < n - 1; ++j) {
            for (int i = 0; i < m - 1; ++i) {
                ans = Math.min(ans, getArea(grid, 0, 0, i, j) + getArea(grid, i + 1, 0, m - 1, j) + getArea(grid, 0, j + 1, m - 1, n - 1));
                ans = Math.min(ans, getArea(grid, 0, 0, m - 1, j) + getArea(grid, 0, j + 1, i, n - 1) + getArea(grid, i + 1, j + 1, m - 1, n - 1));
            }
        }
        return ans;
    }
}

